// SMPC firmware: the SMPC's HMCS400 MCU program (smpc.mif), translated to C by smpc_gen/gen_mcu.py (obj/smpc_mcu_gen.c,
// generated by build.sh), and the runtime it runs on (smpc_rt.c): the MCU's mapped registers, timers, interrupt controller,
// ports and RAM map as SMPC.sv has them, evaluated at the CE times the program touches them.
//
// Time: SMPC_CE edges since RST_N (CE #1 is MRES_N's edge: the MCU is still in reset there). From CE #2 on CYC rotates:
// CYC[0] edges are CE #4k+2, CYC[1] #4k+3, CYC[2] #4k+4, CYC[3] #4k+5; instruction states end on CYC[3] edges (the
// first one on CE #5). The world (the bench, or the firmware's hardware layer) gives the inputs at a CE time and takes
// the outputs with their CE time (w_* below).
#pragma once
#include <stdint.h>
#include <stddef.h>

typedef struct {
	uint8_t A, B, X, Y, W, sx, sy, CA, ST, SP;   // sx / sy: SPX / SPY
	uint32_t vt;                      // CE time of the CYC[3] edge that ended the last state executed
	void* resume;                     // where mcu_exec() continues (a label in it)
	void* shadow[16];                 // return labels of the RAM stack's 16 entries (by entry index SP[5:2])
	uint8_t novt_latch;               // vt is a wake-up edge, not the end of an instruction: no interrupt latch there
	uint8_t sby_latch;                // the core latched INT_EXP at the SBY instruction's edge
	uint8_t halted;                   // STOP executed, or the program left the translated code
	uint8_t waiting;                  // stopped in SBY or an idle loop: the world did not know its inputs far enough;
	                                  // run again when an input changes, or at m.wake_at at the latest
	uint32_t wake_at;                 // stopped: the edge from which running again makes progress
	uint32_t fail;
	uint16_t pc;                      // faithful build: the PC of the instruction the run stopped before
} mcu_t;
extern mcu_t m;
extern uint8_t mre[32];               // MR (16 nibbles, 040-04F) then ERAM (16 nibbles, 260-26F): SMPC.sv's MRE RAM
extern uint8_t stk[64];               // RAM 3C0-3FF (HMCS400_STACK): the stack (16 x 4 nibbles), variables below it

typedef struct {
	uint8_t INTC[4], RF[4], PMRB, PMRC, ESR1, TMA, TMC1, TWCL, TWCU, TRCL, TRCU, DCD[4], DCR[8];
	uint16_t D_O;                     // D port output latches
	uint8_t R_O[8];                   // R port output latches
	uint8_t TCA, TCC, TA_OVF, TC_OVF, TC_UPD, PSW;
	uint16_t PSS;
	uint8_t comreg_pend, comreg_int;  // SMPC.sv COMREG_PEND / COMREG_INT
	uint8_t old0, old1, old2, old3;   // INT0_N / INT1_N / INT2 / INT3 as sampled at the last CYC[1] edge
	uint32_t t;                       // CE edges processed up to (and including) this one
	uint32_t t0;                      // CE #n is the edge t0 + n (0 in the firmware; benches move it to test the wrap)
	uint32_t snap_t; uint8_t snap_pend;   // the core's INT_PEND just before the register write at edge snap_t
	uint32_t nev;                     // peripheral events processed (event model)
} periph_t;
extern periph_t P;

void mcu_reset(int power_on);                 // RST_N: registers, peripherals, the program at 000 (vt = 1)
void mcu_exec(void);                          // run (smpc_mcu_gen.c)
void periph_to(uint32_t t);                   // process the CE edges up to t (timers, edge detectors, COMREG handshake)
uint32_t periph_next_event(uint32_t t);       // the next edge after t where the peripherals' state may change
void periph_materialize(uint32_t t);          // periph_to(t), and the counters the event model keeps implicit (PSS..)
void periph_dirty(void);                      // the world knows of a new input change (VBLANK, COMREG): events again
uint8_t reg_rd(int a, uint32_t t);            // mapped register read; t = the state's CYC[3] edge
void reg_wr(int a, uint8_t v, uint32_t t);
uint8_t ram_rd(int a, uint32_t t);            // a {W,X,Y} address (any region)
void ram_wr(int a, uint8_t v, uint32_t t);
uint8_t io_rd_d(int n, uint32_t t);           // TD / TDD: D pin n (in all 4 bits)
uint8_t io_rd_r(int n, uint32_t t);           // LAR / LBR: R port n
uint8_t io_rd_v(int iop, int a, uint32_t t);
void io_wr_d(int n, uint8_t v, uint32_t t);   // SED / RED / SEDD / REDD (bit 0 of v)
void io_wr_r(int n, uint8_t v, uint32_t t);   // LRA / LRB
void io_wr_v(int iop, int a, uint8_t v, uint32_t t);
void oreg_wr(int a, uint8_t v, uint32_t t);   // 320-35F: OREG nibbles
void sreg_wr(int a, uint8_t v, uint32_t t);   // 360: SR[7:4], 361: SR[3:0], 362: SF clear
uint16_t rom_pattern(int a, uint32_t t);      // P: ROM word at a (IREG at FF0-FFF), read at CE edge t (CYC[1])
uint8_t rtc_init(int i, uint32_t t);          // ROM 0681-068E: low nibble from RTC_INIT[i], fetched at CE edge t
int int_latch(uint32_t t);                    // the core's INT_PEND (IE and an interrupt) before the CYC[3] edge t
int int_vector(uint32_t t);                   // INT_VEC before the edge t (1..5)
uint32_t wake_time(uint32_t t);               // SBY from edge t: the first CYC[3] edge with an interrupt pending (0 = not yet)
void int_accept(uint32_t t);                  // INT_ACP at the edge t: IE = 0
void int_return(uint32_t t);                  // INT_RET (RTNI) at the edge t: IE = 1

// the world
uint8_t w_d3(uint32_t t);                     // reset button (D3), 1 = not pressed
uint8_t w_vbl_n(uint32_t t);                  // R01: VDP2 VBLANK (IRQV_N), 0 = in VBLANK
uint32_t w_vbl_next(uint32_t after);          // the first edge > after where IRQV_N differs from its value at after
                                              // (0: none up to w_limit())
uint32_t w_comreg_next(void);                 // the edge from which the oldest COMREG write not taken by w_comreg is
                                              // visible (0: none up to w_limit())
uint32_t w_limit(void);                       // the world knows its inputs up to this edge
uint8_t w_pio(int port, uint32_t t);          // PIOA_I (0) / PIOB_I (1)
uint8_t w_area(void);                         // R5
uint8_t w_ireg(int i, uint32_t t);            // IREG0-6; 7 = COMREG
void w_ireg_watch(uint8_t v);                 // the program stopped in a loop that reads IREG0 (seen as v): a change
                                              // of IREG0 is an input change (run it again)
int w_comreg(uint32_t t);                     // the host wrote COMREG and the write is seen by the CE edge t (once)
void w_d_out(uint16_t pins, uint32_t t);      // D pins (D_O | ~D_D) after a change at the edge t
void w_r_out(int n, uint8_t o, uint8_t dcr, uint32_t t);   // R port n latch / direction after a change
void w_oreg(int i, uint8_t v, uint32_t t);
void w_sr(uint8_t v, uint32_t t);
void w_sfclr(uint32_t t);
uint8_t w_rtc_init(int i);                    // RTC_INIT[i] (SMPC.sv's capture of EXT_RTC)
void w_sync(uint32_t t);                      // the program accesses the world at CE edge t: its inputs up to t are known
void w_fail(uint32_t pc);
extern const uint16_t mcu_rom_010[16];           // ROM 010-01F (the month table the program reads with P 0)
#ifdef MCU_FAITHFUL
extern int mcu_step_stop;
void mcu_ret_tables(const uint16_t* pcs, void* const* labels, int n);
int rtn_check(uint16_t pc, void* l);
#endif

// ---- used by the generated code
#define MCU_LOCALS \
	unsigned A, B, X, Y, W, SPX, SPY, CA, ST, SP, m_ = 0, c_ = 0; unsigned t_ = 0; unsigned p_ = 0; uint32_t vt; \
	void* resume_ = 0; \
	unsigned nA_, nB_, nX_, nY_, nW_, nSPX_, nSPY_, nCA_, nST_, nSP_; \
	(void)c_; (void)p_; (void)m_; (void)t_; (void)nA_; (void)nB_; (void)nX_; (void)nY_; (void)nW_; (void)nSPX_; \
	(void)nSPY_; (void)nCA_; (void)nST_; (void)nSP_
#define MCU_LOAD  A = m.A; B = m.B; X = m.X; Y = m.Y; W = m.W; SPX = m.sx; SPY = m.sy; CA = m.CA; ST = m.ST; SP = m.SP; vt = m.vt
#define MCU_SAVE  m.A = A; m.B = B; m.X = X; m.Y = Y; m.W = W; m.sx = SPX; m.sy = SPY; m.CA = CA; m.ST = ST; m.SP = SP; m.vt = vt
#define MCU_PROLOGUE MCU_LOAD; if (m.halted) return; if (!m.resume) m.resume = &&L_000; goto *m.resume
#define MCU_EPILOGUE return; mcu_stop_: MCU_SAVE; m.resume = resume_; return
#define MCU_STOP_AT(label) do { resume_ = &&label; goto mcu_stop_; } while (0)
#define MCU_FAIL(pc) do { MCU_SAVE; m.fail = (pc); m.halted = 1; w_fail(pc); return; } while (0)

// push {ST, PC[13:7], CA, PC[6:0]} into the stack entry SP[5:2]
void mcu_push(unsigned sp, unsigned st, unsigned ca, unsigned pc, void* label);
#define PUSH(pc, label) mcu_push(SP, ST, CA, (pc), (label))

// RTN (r = 0) / RTNI (r = 1), after the instruction's 3 states (vt - 4: state 1's edge, where RTNI sets IE)
#ifdef MCU_FAITHFUL
#define RTN(r) do { int e_ = SP & 0x3C; void* l_ = m.shadow[e_ >> 2]; \
	uint16_t pc_ = (uint16_t)(((stk[e_] & 7) << 11) | (stk[e_ + 1] << 7) | ((stk[e_ + 2] & 7) << 4) | stk[e_ + 3]); \
	if (r) int_return(vt - 4); \
	if (!rtn_check(pc_, l_)) MCU_FAIL(0x10000 | pc_); \
	goto *l_; } while (0)
#else
#define RTN(r) do { void* l_ = m.shadow[(SP & 0x3C) >> 2]; if (r) int_return(vt - 4); goto *l_; } while (0)
#endif

// TBR p: PC = {00, p, B, A}; the program has only TBR 1 (the command dispatch, B:A < 0x20)
#define TBR(p) do { if (((B << 4) | A) >= 32) MCU_FAIL(0x100 | (B << 4) | A); goto *tbr1[(B << 4) | A]; } while (0)

// the interrupt sequence (2 states) instead of the instruction at pc, if the core latched INT_EXP at the end of the
// previous instruction (edge vt): state 0 (ST = 1, INT_ACP: IE = 0, VEC latched), state 1 (push, SP - 4, PC = VEC * 2)
#define MCU_INT_SEQ(pc_, label) do { \
	if (!m.novt_latch && int_latch(vt)) { \
		int v_ = int_vector(vt + 4); \
		ST = 1; int_accept(vt + 4); \
		PUSH(pc_, &&label); \
		SP = (SP - 4) & 63; vt += 8; \
		goto *vec_label[v_]; \
	} \
	m.novt_latch = 0; } while (0)

// an instruction boundary: interrupt check (main loop only); faithful build: a stop point at every boundary
#ifdef MCU_FAITHFUL
#define MCU_STEP(label, pc_) \
	if (mcu_step_stop) { mcu_step_stop = 0; m.pc = (pc_); MCU_STOP_AT(label##_go); } \
	label##_go: mcu_step_stop = 1; \
	MCU_INT_SEQ(pc_, label)
#else
#define MCU_STEP(label, pc_) MCU_INT_SEQ(pc_, label)
#endif

// fast build: a world access follows; the run may stop here (and run the whole instruction again later).
// MCU_FASTCHECK (benches): the PC of the instruction is kept for comparisons at the stop.
#ifdef MCU_FASTCHECK
#define MCU_SETPC(pc_) (m.pc = (pc_))
#else
#define MCU_SETPC(pc_) ((void)0)
#endif
// MCU_YIELD(label, pc, D) at the start of a block with world accesses: they end by vt + D; if the world does not know
// its inputs that far (mcu_lim, refreshed by the world before each run), stop here (run again from the label when it
// does: m.wake_at)
extern uint32_t mcu_lim;
// the world may cap a run at MCU_RUN_CAP edges of the program's time (mcu_lim <= vt + MCU_RUN_CAP): every block's D is
// at most that (gen_mcu.py checks), so a run always gets through the next block
#ifndef MCU_RUN_CAP
#define MCU_RUN_CAP 400
#endif
#define MCU_RUN_MIN 64          // the shortest cap a run may get: the longest block's D (gen_mcu.py checks)
// mcu_brk (smpc_world.c smpc_poll_main): a CD command waiting for the CD code stops the run here too (the same stop:
// the block runs again from its label in a later poll)
// (mcu_brk_p points at IO_FLAGS (hw.h: bit 0 = CMD_PEND) while the break is armed, else at a zero word: one load, one
// dereference per yield check, 188 sites)
extern volatile const uint32_t* mcu_brk_p;
#ifndef CDFW_NOFIX
#define MCU_BRK() (*mcu_brk_p & 1u)
#else
#define MCU_BRK() 0
#endif
#define MCU_YIELD(label, pc_, D) do { if ((int32_t)(mcu_lim - (vt + (D))) < 0 || MCU_BRK()) { \
	MCU_SETPC(pc_); m.waiting = 0; m.wake_at = vt + (D); MCU_STOP_AT(label); } } while (0)

// fast build: the head of an idle loop (gen_mcu.py IDLE): idle_head() returns the CE edges of the passes it skips; it
// sets m.waiting when the world does not know the inputs of the next pass yet (stop at the head, run it again later)
#define IDLE_VBL 1                    // the body reads R0 (VBLANK, COMREG_INT) and peripheral flags
#define IDLE_TCC 2                    // the body reads TRCU / TRCL (timer C) and peripheral flags
#define IDLE_TCMP 4                   // loop 02B9 (gen_mcu.py checks its listing): waits until timer C >= ERAM0:ERAM1;
                                      // a pass is 24 CE while TRCU < ERAM0, 56 CE while TRCU = ERAM0, TRCL < ERAM1
#define IDLE_IREG 8                   // the body reads IREG0 (P at FF0; loop 0615, INTBACK's continue / break wait)
#define MCU_NIDLE 5                   // idle loops (gen_mcu.py IDLE; the generated code checks)
uint32_t idle_head(int i, int h, uint32_t vt, uint32_t k0, uint32_t k1);
#define MCU_IDLE(label, pc_, i, h) do { \
	vt += idle_head((i), (h), vt, (uint32_t)A | (uint32_t)B << 4 | (uint32_t)X << 8 | (uint32_t)Y << 12 | (uint32_t)W << 16 | \
	                (uint32_t)SPX << 20 | (uint32_t)SPY << 24 | (uint32_t)CA << 28 | (uint32_t)ST << 29, SP); \
	if (m.waiting) { MCU_SETPC(pc_); MCU_STOP_AT(label); } } while (0)

// benches: a hook at every block start of the fast build
#ifdef MCU_LEADHOOK
void mcu_lead_hook(unsigned pc, uint32_t vt, unsigned A, unsigned B, unsigned X, unsigned Y, unsigned W, unsigned SPX,
                   unsigned SPY, unsigned CA, unsigned ST, unsigned SP);
#define MCU_LEAD(pc_) mcu_lead_hook((pc_), vt, A, B, X, Y, W, SPX, SPY, CA, ST, SP)
#else
#define MCU_LEAD(pc_) ((void)0)
#endif

// fast build profile: instructions executed per address (the delay routine counts as one at 0D6)
#ifdef MCU_PROFILE
extern uint32_t mcu_count[2048];
#define MCU_COUNT(pc_) (mcu_count[(pc_)]++)
#else
#define MCU_COUNT(pc_) ((void)0)
#endif
